std::vector<Polygon2d> faces;
Arrangement::Face_const_iterator fit;
for (fit = arr.faces_begin(); fit != arr.faces_end(); ++fit) {
    if (fit->is_unbounded()) continue;
    Polygon2d polygon;
    Arrangement::Ccb_halfedge_const_circulator ec = fit->outer_ccb();
    Arrangement::Ccb_halfedge_const_circulator ec_start = ec;
    do {
        const Point2d p(CGAL::to_double(ec->source()->point().x()),
                        CGAL::to_double(ec->source()->point().y()));
        polygon.pushBack(p);
        ++ec;
    } while (ec != ec_start);
    faces.push_back(polygon);
}
return faces;

